<?php

namespace App\Controllers;

use App\Core\Auth;
use App\Core\Database;
use App\Core\Flash;
use App\Core\Request;
use App\Models\AuditLog;
use App\Models\User;
use App\Services\AuthenticationService;

/**
 * One-time initial Dean creation.
 *
 * Guarded by a random setup token generated by tools/install.php and written
 * to storage/setup_token.txt (outside the public web root). The page is
 * permanently disabled once a Dean exists. No default password is shipped.
 */
final class SetupController extends Controller
{
    public function index(): void
    {
        if (User::deanExists()) {
            abort(403, 'Initial setup has already been completed. Please sign in.');
        }

        $tokenFile = BASE_PATH . '/storage/setup_token.txt';
        $tokenAvailable = is_file($tokenFile);

        $this->render('setup/index', [
            'pageTitle'      => 'Initial setup',
            'bodyClass'      => 'auth-body',
            'tokenAvailable' => $tokenAvailable,
        ], 'layouts/auth');
    }

    public function store(): void
    {
        if (User::deanExists()) {
            abort(403, 'Initial setup has already been completed.');
        }

        $tokenFile = BASE_PATH . '/storage/setup_token.txt';
        if (!is_file($tokenFile)) {
            Flash::error('The setup token file is missing. Run "php tools/install.php" to generate it.');
            redirect('/setup');
        }

        $expectedToken = trim((string) file_get_contents($tokenFile));
        $providedToken = trim((string) Request::input('setup_token', ''));

        if ($expectedToken === '' || !hash_equals($expectedToken, $providedToken)) {
            AuditLog::record(null, 'setup.token_invalid', 'Setup', 'initial-dean', 'Invalid setup token supplied.');
            Flash::error('The setup token is invalid.');
            redirect('/setup');
        }

        $data = [
            'full_name' => trim((string) Request::input('full_name', '')),
            'username'  => trim((string) Request::input('username', '')),
            'email'     => trim((string) Request::input('email', '')),
            'password'  => (string) Request::input('password', ''),
        ];

        $validated = $this->validate($data, [
            'full_name' => 'required|max:150',
            'username'  => 'required|username|unique:users,username',
            'email'     => 'required|email|max:190|unique:users,email',
            'password'  => 'required|password_strength|confirmed',
        ], [
            'full_name' => 'Full name',
            'username'  => 'Username',
            'email'     => 'Email address',
            'password'  => 'Password',
        ], '/setup');

        $service = new AuthenticationService();

        $userId = Database::transaction(static function () use ($validated, $service): int {
            if (User::deanExists()) {
                throw new \RuntimeException('A Dean account already exists.');
            }
            return User::create([
                'full_name'     => $validated['full_name'],
                'username'      => $validated['username'],
                'email'         => $validated['email'],
                'password_hash' => $service->hash($validated['password']),
                'role'          => 'Dean',
                'account_status'=> 'Active',
            ]);
        });

        @unlink($tokenFile);
        AuditLog::record($userId, 'setup.dean_created', 'Setup', 'user:' . $userId, 'Initial Dean account created via one-time setup token.');
        AuditLog::record($userId, 'setup.completed', 'Setup', 'initial-setup', 'Initial setup completed; setup token destroyed.');

        Auth::login(User::findForSession($userId) ?? ['user_id' => $userId, 'role' => 'Dean']);
        Flash::success('Your Dean account has been created. Welcome to ICOTAS.');
        redirect('/dean/dashboard');
    }
}
